# VeriPusula - KPI Analysis Engine

rows = [item["json"] for item in _items]

if not rows:
    raise ValueError("Satis verisi bulunamadi")

total_revenue = 0
total_profit = 0
orders = set()

categories = {}
months = {}
products = {}

def add_group(group, key, revenue, profit):
    if key not in group:
        group[key] = {"revenue": 0, "profit": 0}

    group[key]["revenue"] += revenue
    group[key]["profit"] += profit


for row in rows:
    revenue = float(row["revenue"])
    profit = float(row["profit"])

    total_revenue += revenue
    total_profit += profit
    orders.add(row["order_id"])

    add_group(categories, row["category"], revenue, profit)
    add_group(months, row["year_month"], revenue, profit)
    add_group(products, row["product"], revenue, profit)


def format_group(group, field):
    result = []

    for name, values in group.items():
        rev = values["revenue"]
        pro = values["profit"]

        result.append({
            field: name,
            "revenue": round(rev, 2),
            "profit": round(pro, 2),
            "margin_pct": round(pro / rev * 100, 2) if rev else 0
        })

    return result


category_results = sorted(
    format_group(categories, "category"),
    key=lambda x: x["revenue"],
    reverse=True
)

monthly_results = sorted(
    format_group(months, "month"),
    key=lambda x: x["month"]
)

top_products = sorted(
    format_group(products, "product"),
    key=lambda x: x["revenue"],
    reverse=True
)[:5]

profit_margin = (
    total_profit / total_revenue * 100
    if total_revenue else 0
)

return [{
    "json": {
        "project": "VeriPusula",
        "total_revenue": round(total_revenue, 2),
        "total_profit": round(total_profit, 2),
        "order_count": len(orders),
        "profit_margin_pct": round(profit_margin, 2),
        "category_performance": category_results,
        "monthly_performance": monthly_results,
        "top_5_products": top_products
    }
}]
